with base as (select *, round(budget, 1) as budget_rounded, coalesce(budget, 0) as budget_filled, coalesce(dept_name, 'OTHER') as resolved_dept_name from departments where dept_name is not null) select * from (select dept_name, location, budget_filled from base) src pivot (sum(budget_filled) as amount, count(1) as item_count for location in ('Tokyo' as tokyo, 'Bangkok' as bangkok, 'London' as london));
